'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const GATEWAY='https://rwl-movies-gateway.rwl98.workers.dev', IMG='https://image.tmdb.org/t/p/';
const state={lang:localStorage.getItem('rwlLang')||'ar',page:'home',home:null,detail:null,type:null,season:1,episode:1,servers:[],subtitles:[],activeServer:null,genres:null};
const themes={cyan:['#00bfea','#00e5ff','#080a0f','#12151e'],amber:['#f59e0b','#fcd34d','#0f0c06','#1a160e'],red:['#e50914','#ff4d4d','#0e0607','#1a0c0e'],blue:['#3b82f6','#60a5fa','#060b14','#0e1726'],green:['#10b981','#34d399','#060f0b','#0e1a14'],pink:['#ff1493','#ff80bf','#14050e','#220a18']};
function tr(ar,en){return state.lang==='ar'?ar:en} function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function api(path,opt){return fetch(GATEWAY+path,{headers:{Accept:'application/json','Content-Type':'application/json',...(opt?.headers||{})},...opt}).then(async r=>{let b={};try{b=await r.json()}catch{} if(!r.ok) throw new Error(b.message||`HTTP_${r.status}`); return (path.startsWith('/v1/tmdb/details')&&b?.item)?b.item:b})}
function open(id){$('#'+id).classList.add('open')} function close(id){$('#'+id).classList.remove('open')} function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),2200)}
function poster(x,s='w500'){return x?.poster_path?IMG+s+x.poster_path:''} function backdrop(x,s='original'){return x?.backdrop_path?IMG+s+x.backdrop_path:''} function title(x){return x?.title||x?.name||x?.original_title||x?.original_name||''} function year(x){return String(x?.release_date||x?.first_air_date||'').slice(0,4)} function typeOf(x){return x?.media_type==='tv'||(!x?.title&&x?.name)?'tv':'movie'}
function route(r){location.hash=r.startsWith('#')?r:'#'+r} function parseRoute(){return location.hash.replace(/^#/,'')||'home'}
function favs(){try{return JSON.parse(localStorage.getItem('rwlFavs')||'[]')}catch{return[]}} function saveFavs(v){localStorage.setItem('rwlFavs',JSON.stringify(v))}
function card(x,rank=''){const type=typeOf(x),id=x.id,p=poster(x),t=title(x);return `<article class="posterCard" data-detail="${type}/${id}">${p?`<img src="${p}" loading="lazy">`:''}<div class="posterShade"></div>${rank?`<span class="rankNum">${rank}</span>`:''}<div class="posterCopy"><b>${esc(t)}</b><small>${esc([year(x),x.vote_average?`★ ${Number(x.vote_average).toFixed(1)}`:''].filter(Boolean).join(' • '))}</small></div></article>`}
function row(items,top10=false){return (items||[]).filter(x=>x?.id&&x.media_type!=='person').slice(0,24).map((x,i)=>card(x,top10?i+1:'')).join('')||`<div class="empty">${tr('لا توجد نتائج','No results')}</div>`}
function section(name,items,top10=false,more=''){return `<section class="section"><div class="sectionHead"><h2>${esc(name)}</h2>${more?`<button data-route="${more}">${tr('عرض الكل','See all')}</button>`:''}</div><div class="horizontal">${row(items,top10)}</div></section>`}
function castRow(c){return `<div class="castRow">${(c||[]).slice(0,18).map(p=>`<div class="castCard">${p.profile_path?`<img src="${IMG}w185${p.profile_path}">`:''}<b>${esc(p.name)}</b></div>`).join('')}</div>`}
function dockV6(){const items=[['home','⌂',tr('الرئيسية','Home')],['discover','◈',tr('استكشاف','Discover')],['manga','▤',tr('مانجا','Manga')],['books','▥',tr('مكتبة','Library')],['anime','✦',tr('أنمي','Anime')],['music','♫',tr('موسيقى','Music')],['mylist','♥',tr('قائمتي','My List')]];$('#dock').innerHTML=items.map(([k,i,n])=>`<button class="dockBtn ${state.page===k?'active':''}" data-route="${k}"><span class="dockIcon">${i}</span><span>${n}</span></button>`).join('')}
function setTop(t){$('#topTitle').textContent=t}
async function homeV6(){state.page='home';dock();setTop(tr('الرئيسية','Home')); if(!state.home) state.home=await api(`/v1/tmdb/home?language=${state.lang==='ar'?'ar-SA':'en-US'}`); const h=state.home, hero=(h.trending||[]).find(x=>x.media_type!=='person')||h.movies?.[0]; const detail=await api(`/v1/tmdb/details?type=${typeOf(hero)}&id=${hero.id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>hero); const trailer=(detail.videos?.results||[]).find(v=>v.site==='YouTube'&&v.type==='Trailer'); let html=`<section class="hero" style="background-image:url('${backdrop(hero)}')">${trailer?`<div class="heroVideo"><iframe src="https://www.youtube.com/embed/${trailer.key}?autoplay=1&mute=1&controls=0&loop=1&playlist=${trailer.key}&playsinline=1&modestbranding=1" allow="autoplay"></iframe></div>`:''}<div class="heroCopy"><div class="eyebrow">${esc([year(hero),typeOf(hero)==='tv'?tr('مسلسل','TV'):tr('فيلم','Movie'),hero.vote_average?`★ ${Number(hero.vote_average).toFixed(1)}`:''].filter(Boolean).join(' • '))}</div><h1>${esc(title(hero))}</h1><p>${esc(hero.overview||'')}</p><div class="actions"><button class="primary" data-detail="${typeOf(hero)}/${hero.id}">ⓘ ${tr('التفاصيل','Details')}</button><button class="secondary" data-route="discover">✦ ${tr('استكشاف','Discover')}</button></div></div></section>`;
 html+=section(tr('أفضل 10 هذا الأسبوع','Top 10 This Week'),(h.trending||[]).filter(x=>x.media_type!=='person').slice(0,10),true);
 html+=section(tr('أفلام شائعة','Popular Movies'),h.movies,false,'genre/movie/all')+section(tr('مسلسلات شائعة','Popular TV'),h.tv,false,'genre/tv/all');
 $('#view').innerHTML=html+`<section class="section"><div class="sectionHead"><h2>${tr('التصنيفات','Genres')}</h2></div><div id="genreGrid" class="genreGrid"></div></section><section class="section"><div class="sectionHead"><h2>${tr('ممثلون رائجون','Trending Cast')}</h2></div><div id="peopleGrid" class="personGrid"></div></section>`; await fillGenres(); await fillPeople(); await addGenreSections(); bindDynamic(); }
async function fillGenres(){const [m,t]=await Promise.all([api(`/v1/tmdb/genres?type=movie&language=${state.lang==='ar'?'ar-SA':'en-US'}`),api(`/v1/tmdb/genres?type=tv&language=${state.lang==='ar'?'ar-SA':'en-US'}`)]);state.genres={movie:m.genres||[],tv:t.genres||[]};const wanted=['Action','Comedy','Romance','Horror','Science Fiction','Animation','Crime','Family','Drama','Thriller'];const cards=(m.genres||[]).filter(g=>wanted.includes(g.name)||state.lang==='ar').slice(0,12).map(g=>`<div class="genreCard" data-route="genre/movie/${g.id}">${esc(g.name)}</div>`).join('');$('#genreGrid').innerHTML=cards}
async function addGenreSections(){if(!state.genres)return; const keys=['Comedy','Romance','Horror','Action','Animation']; for(const name of keys){const g=state.genres.movie.find(x=>x.name===name); if(!g)continue; const d=await api(`/v1/tmdb/discover?type=movie&genre=${g.id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>null); if(d?.results) $('#view').insertAdjacentHTML('beforeend',section(g.name,d.results,false,`genre/movie/${g.id}`));} bindDynamic()}
async function fillPeople(){const d=await api(`/v1/tmdb/people?language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({results:[]}));$('#peopleGrid').innerHTML=(d.results||[]).slice(0,16).map(p=>`<div class="personCard">${p.profile_path?`<img src="${IMG}w342${p.profile_path}">`:''}<b>${esc(p.name)}</b></div>`).join('')}
async function discover(type='all'){state.page='discover';dock();setTop(tr('استكشاف','Discover'));const d=await api(`/v1/tmdb/trending?type=${type}&window=week&language=${state.lang==='ar'?'ar-SA':'en-US'}`);$('#view').innerHTML=`<div class="page"><h1>${tr('استكشاف','Discover')}</h1><div class="actions"><button class="secondary" data-route="discover/all">${tr('الكل','All')}</button><button class="secondary" data-route="discover/movie">${tr('أفلام','Movies')}</button><button class="secondary" data-route="discover/tv">${tr('مسلسلات','TV')}</button></div><div class="mediaGrid" style="margin-top:20px">${row(d.results)}</div></div>`;bindDynamic()}
async function genrePage(type,id){state.page='discover';dock();const d=await api(`/v1/tmdb/discover?type=${type}&genre=${id==='all'?'':id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`);$('#view').innerHTML=`<div class="page"><h1>${tr('التصنيف','Genre')}</h1><div class="mediaGrid">${row(d.results)}</div></div>`;bindDynamic()}
async function detailPageV6(type,id,season=1,episode=1){state.page='detail';dock();state.type=type;state.season=Number(season)||1;state.episode=Number(episode)||1;const d=await api(`/v1/tmdb/details?type=${type}&id=${id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`);state.detail=d; const trailer=(d.videos?.results||[]).find(v=>v.site==='YouTube'&&v.type==='Trailer'); const isFav=favs().some(x=>x.type===type&&x.id==id); let seasonUI=''; if(type==='tv'){seasonUI=`<section class="sourceLane"><h3>${tr('المواسم والحلقات','Seasons & Episodes')}</h3><div class="seasonTabs">${(d.seasons||[]).filter(s=>s.season_number>0).map(s=>`<button class="${s.season_number===state.season?'active':''}" data-season="${s.season_number}">${tr('الموسم','Season')} ${s.season_number}</button>`).join('')}</div><div id="episodeList" class="episodeList"></div></section>`}
 $('#view').innerHTML=`<section class="detailHero" style="background-image:url('${backdrop(d)}')"><div class="detailContent"><div class="eyebrow">${esc([year(d),d.vote_average?`★ ${Number(d.vote_average).toFixed(1)}`:''].filter(Boolean).join(' • '))}</div><h1>${esc(title(d))}</h1><div class="actions"><button class="primary" id="watchNow">▶ ${tr('شاهد الآن','Watch Now')}</button>${trailer?`<button class="secondary" id="trailerBtn">▷ ${tr('التريلر','Trailer')}</button>`:''}<button class="secondary" id="favBtn">${isFav?'♥':'♡'} ${tr('قائمتي','My List')}</button></div></div></section><div class="detailBody"><p>${esc(d.overview||'')}</p><section><h3>${tr('طاقم التمثيل','Cast')}</h3>${castRow(d.credits?.cast)}</section>${seasonUI}<section class="sourceLane"><h3>${tr('المصادر','Sources')}</h3><div id="sourceStatus" class="eyebrow">${tr('جاري البحث عن السيرفرات…','Finding servers…')}</div><div id="directLane"></div><div id="totLane"></div></section>${section(tr('قد يعجبك أيضاً','You may also like'),d.recommendations?.results||d.similar?.results||[])}</div>`; bindDynamic();
 $('#favBtn').onclick=()=>toggleFav(type,id); if(trailer) $('#trailerBtn').onclick=()=>window.open(`https://www.youtube.com/watch?v=${trailer.key}`,'_blank'); $('#watchNow').onclick=()=>{document.getElementById('directLane')?.querySelector('.source')?.click()||toast(tr('لا يوجد مصدر جاهز بعد','No ready server yet'))}; if(type==='tv'){await loadEpisodes(id,state.season); $$('[data-season]').forEach(b=>b.onclick=async()=>{state.season=Number(b.dataset.season);state.episode=1;$$('[data-season]').forEach(x=>x.classList.toggle('active',x===b));await loadEpisodes(id,state.season);await loadSources(type,id)})} await loadSources(type,id)}
async function loadEpisodes(id,season){const d=await api(`/v1/tmdb/season?id=${id}&season=${season}&language=${state.lang==='ar'?'ar-SA':'en-US'}`);$('#episodeList').innerHTML=(d.episodes||[]).map(e=>`<div class="episodeCard ${e.episode_number===state.episode?'active':''}" data-episode="${e.episode_number}">${e.still_path?`<img src="${IMG}w300${e.still_path}">`:''}<div><b>${tr('الحلقة','Episode')} ${e.episode_number}: ${esc(e.name||'')}</b><p>${esc(e.overview||'')}</p></div></div>`).join('');$$('[data-episode]').forEach(x=>x.onclick=async()=>{state.episode=Number(x.dataset.episode);await loadSources('tv',id)})}
function idsQuery(type,id){const imdb=state.detail?.external_ids?.imdb_id||'';return `type=${type}&tmdb=${id}${imdb?`&imdb=${encodeURIComponent(imdb)}`:''}${type==='tv'?`&season=${state.season}&episode=${state.episode}`:''}`}
async function loadSources(type,id){$('#sourceStatus').textContent=tr('جاري البحث عن السيرفرات…','Finding servers…');let data=await api(`/v1/web/sources?${idsQuery(type,id)}`).catch(()=>({servers:[]}));let servers=data.servers||[];const cfg=JSON.parse(localStorage.getItem('rwlDebrid')||'null');if(cfg?.key&&cfg?.provider){try{const t=await api(`/v1/web/torrents?${idsQuery(type,id)}`);for(const tor of (t.torrents||[]).slice(0,4)){const r=await api('/v1/web/debrid/resolve',{method:'POST',body:JSON.stringify({provider:cfg.provider,key:cfg.key,magnet:tor.magnet,filename:tor.filename,fileIndex:tor.fileIndex,season:state.season,episode:state.episode,cachedOnly:true})}).catch(()=>null);if(r?.ok&&r.url)servers.push({id:`user-${servers.length+1}`,label:`Server ${servers.length+1}`,lane:'p2p',url:r.url,qualities:[]})}}catch{}}
 state.servers=servers;const direct=servers.filter(s=>s.lane!=='p2p'),tot=servers.filter(s=>s.lane==='p2p');$('#directLane').innerHTML=direct.length?`<h3>RWL DIRECT</h3><div class="sources">${direct.map((s,i)=>sourceButton(s,i)).join('')}</div>`:'';$('#totLane').innerHTML=tot.length?`<h3>RWL TOT</h3><div class="sources">${tot.map((s,i)=>sourceButton(s,direct.length+i)).join('')}</div>`:'';$('#sourceStatus').textContent=servers.length?`${servers.length} ${tr('سيرفر متاح','servers available')}`:tr('لا توجد مصادر حالياً','No sources available');$$('.source').forEach(b=>b.onclick=()=>playServer(servers[Number(b.dataset.i)],Number(b.dataset.i)+1,type,id));}
function sourceButton(s,i){return `<button class="source" data-i="${i}"><b>Server ${i+1}</b><small>${s.lane==='p2p'?'RWL TOT':'RWL DIRECT'}</small></button>`}
async function playServer(s,num,type,id){state.activeServer=s;$('#playerTitle').textContent=title(state.detail);$('#playerServer').textContent=`Server ${num}`;$('#playerLane').textContent=s.lane==='p2p'?'RWL TOT':'RWL DIRECT';const v=$('#webPlayer');v.src=s.url;v.playbackRate=1;open('playerOverlay');await loadSubtitles(type,id);v.play().catch(()=>{});}
async function loadSubtitles(type,id){state.subtitles=[];try{const d=await api(`/v1/web/subtitles?${idsQuery(type,id)}`);state.subtitles=d.subtitles||[]}catch{} }
function toggleFav(type,id){let f=favs();const idx=f.findIndex(x=>x.type===type&&x.id==id);if(idx>=0)f.splice(idx,1);else f.unshift({type,id,item:state.detail});saveFavs(f);$('#favBtn').textContent=(idx>=0?'♡':'♥')+' '+tr('قائمتي','My List')}
async function aniV6(kind){state.page=kind;dock();setTop(kind==='manga'?tr('مانجا','Manga'):tr('أنمي','Anime'));const d=await api(`/v1/web/anilist?kind=${kind}`).catch(()=>({items:[]}));$('#view').innerHTML=`<div class="page"><h1>${kind==='manga'?tr('مانجا','Manga'):tr('أنمي','Anime')}</h1>${d.items?.length?`<div class="mediaGrid">${d.items.map(x=>`<div class="posterCard">${x.cover?`<img src="${x.cover}">`:''}<div class="posterShade"></div><div class="posterCopy"><b>${esc(x.title?.userPreferred||x.title?.english||x.title?.romaji||'')}</b><small>${esc([x.year,x.score?`★ ${(x.score/10).toFixed(1)}`:''].filter(Boolean).join(' • '))}</small></div></div>`).join('')}</div>`:`<div class="empty">${tr('تعذر تحميل المكتبة الآن','Library is temporarily unavailable')}</div>`}</div>`}
async function booksV6(){state.page='books';dock();setTop(tr('مكتبة','Library'));const d=await api('/v1/web/books').catch(()=>({books:[]}));$('#view').innerHTML=`<div class="page"><h1>${tr('المكتبة','Library')}</h1>${d.books?.length?`<div class="mediaGrid">${d.books.map(b=>`<div class="posterCard">${b.image?`<img src="${b.image}">`:''}<div class="posterShade"></div><div class="posterCopy"><b>${esc(b.title)}</b><small>${esc((b.authors||[]).join(', '))}</small></div></div>`).join('')}</div>`:`<div class="empty">${tr('تعذر تحميل المكتبة الآن','Library is temporarily unavailable')}</div>`}</div>`}
async function musicV6(){state.page='music';dock();setTop(tr('موسيقى','Music'));const d=await api('/v1/web/music').catch(()=>({tracks:[]}));$('#view').innerHTML=`<div class="page"><h1>${tr('موسيقى','Music')}</h1><div class="libraryList">${(d.tracks||[]).map(t=>`<div class="libraryItem">${t.cover?`<img src="${t.cover}">`:''}<div><b>${esc(t.title)}</b><small>${esc(t.artist)}</small></div><button class="secondary" data-preview="${esc(t.preview)}">▶</button></div>`).join('')}</div></div>`;$$('[data-preview]').forEach(b=>b.onclick=()=>{new Audio(b.dataset.preview).play()})}
function mylist(){state.page='mylist';dock();const f=favs();$('#view').innerHTML=`<div class="page"><h1>${tr('قائمتي','My List')}</h1><div class="mediaGrid">${row(f.map(x=>({...x.item,media_type:x.type})))}</div></div>`;bindDynamic()}
function settingsV6(){const cfg=JSON.parse(localStorage.getItem('rwlDebrid')||'null')||{provider:'torbox',key:''};$('#settingsContent').innerHTML=`<section class="settingsGroup"><h3>${tr('المظهر','Appearance')}</h3><div class="settingRow"><div><b>${tr('اللغة','Language')}</b></div><select id="langSel"><option value="ar">العربية</option><option value="en">English</option></select></div><div class="settingRow"><div><b>${tr('الثيم','Theme')}</b></div><select id="themeSel">${Object.keys(themes).map(k=>`<option value="${k}">${k}</option>`).join('')}</select></div></section><section class="settingsGroup"><h3>${tr('مصادر التشغيل','Playback Sources')}</h3><div class="settingRow"><div><b>${tr('خدمة Debrid','Debrid Service')}</b><small>${tr('المفتاح يحفظ على هذا الجهاز فقط ولا يكتب داخل الموقع.','The key is stored on this device only and is not embedded in the site.')}</small></div><select id="debridProvider"><option value="torbox">TorBox</option><option value="realdebrid">Real-Debrid</option></select></div><div class="settingRow"><div><b>API Key</b><small>${tr('يستخدم فقط عند جلب RWL TOT.','Used only when resolving RWL TOT.')}</small></div><input id="debridKey" type="password" autocomplete="off" value="${esc(cfg.key)}" placeholder="API Key"></div><div class="settingRow"><div><b>${tr('حفظ','Save')}</b></div><button id="saveDebrid" class="primary">${tr('حفظ','Save')}</button></div></section><section class="settingsGroup"><h3>${tr('النسخ والبيانات','Data')}</h3><div class="settingRow"><div><b>${tr('مسح بيانات الموقع','Clear local data')}</b></div><button id="clearData" class="secondary">${tr('مسح','Clear')}</button></div></section>`;$('#langSel').value=state.lang;$('#debridProvider').value=cfg.provider;$('#themeSel').value=localStorage.getItem('rwlTheme')||'cyan';$('#langSel').onchange=e=>{localStorage.setItem('rwlLang',e.target.value);state.lang=e.target.value;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';close('settingsOverlay');renderRoute()};$('#themeSel').onchange=e=>applyTheme(e.target.value);$('#saveDebrid').onclick=()=>{localStorage.setItem('rwlDebrid',JSON.stringify({provider:$('#debridProvider').value,key:$('#debridKey').value.trim()}));toast(tr('تم الحفظ','Saved'))};$('#clearData').onclick=()=>{localStorage.clear();location.reload()};open('settingsOverlay')}
function applyTheme(name=localStorage.getItem('rwlTheme')||'cyan'){localStorage.setItem('rwlTheme',name);const [p,a,b,c]=themes[name]||themes.cyan;const s=document.documentElement.style;s.setProperty('--primary',p);s.setProperty('--accent',a);s.setProperty('--bg',b);s.setProperty('--card',c)}
async function search(q){if(!q.trim()){ $('#searchGrid').innerHTML=''; return}const d=await api(`/v1/tmdb/search?query=${encodeURIComponent(q)}&language=${state.lang==='ar'?'ar-SA':'en-US'}`);$('#searchGrid').innerHTML=row(d.results);bindDynamic()}
function bindDynamic(){$$('[data-detail]').forEach(e=>e.onclick=()=>route(`details/${e.dataset.detail}`));$$('[data-route]').forEach(e=>e.onclick=()=>route(e.dataset.route))}
function playerMenu(type){const m=$('#floatingMenu');m.innerHTML=''; if(type==='speed'){[.5,.75,1,1.25,1.5,2].forEach(x=>m.insertAdjacentHTML('beforeend',`<button data-speed="${x}">${x}×</button>`));$$('[data-speed]').forEach(b=>b.onclick=()=>{$('#webPlayer').playbackRate=Number(b.dataset.speed);$('#speedBtn').textContent=b.dataset.speed+'×';m.classList.remove('open')})} else if(type==='quality'){const q=state.activeServer?.qualities||[];m.innerHTML=`<button data-q="">AUTO</button>`+q.map(x=>`<button data-q="${esc(x.url)}">${esc(x.label||'Quality')}</button>`).join('');$$('[data-q]').forEach(b=>b.onclick=()=>{const v=$('#webPlayer'),pos=v.currentTime,was=!v.paused;if(b.dataset.q)v.src=b.dataset.q;else v.src=state.activeServer.url;v.currentTime=pos;if(was)v.play();m.classList.remove('open')})} else if(type==='sub'){m.innerHTML=`<button data-sub="off">${tr('إيقاف الترجمة','Subtitles Off')}</button>`+(state.subtitles||[]).slice(0,80).map((s,i)=>`<button data-sub="${i}">${esc((s.lang||'')+' '+(s.name||s.label||''))}</button>`).join('');$$('[data-sub]').forEach(b=>b.onclick=async()=>{await setSubtitle(b.dataset.sub);m.classList.remove('open')})} m.classList.toggle('open')}
async function setSubtitle(v){const video=$('#webPlayer');[...video.querySelectorAll('track')].forEach(x=>x.remove());if(v==='off')return;const s=state.subtitles[Number(v)];if(!s)return;try{const txt=await fetch(s.url).then(r=>r.text());let vtt=txt.startsWith('WEBVTT')?txt:'WEBVTT\n\n'+txt.replace(/,(\d{3})/g,'.$1');const blob=URL.createObjectURL(new Blob([vtt],{type:'text/vtt'}));const t=document.createElement('track');t.kind='subtitles';t.label=s.lang||'Subtitle';t.srclang=(s.lang||'en').slice(0,2);t.src=blob;t.default=true;video.appendChild(t);setTimeout(()=>{if(t.track)t.track.mode='showing'},300)}catch{toast(tr('تعذر تحميل الترجمة','Subtitle failed'))}}
function bindPlayerV6(){const v=$('#webPlayer'),stage=$('#videoStage'),seek=$('#seekBar');const sync=()=>{$('#playPauseBtn').textContent=v.paused?'▶':'❚❚';stage.classList.toggle('paused',v.paused);$('#timeText').textContent=`${fmt(v.currentTime)} / ${fmt(v.duration)}`;seek.value=v.duration?Math.round(v.currentTime/v.duration*1000):0};v.onplay=sync;v.onpause=sync;v.ontimeupdate=sync;v.onloadedmetadata=sync;$('#playPauseBtn').onclick=$('#centerPlay').onclick=()=>v.paused?v.play():v.pause();$('#back10Btn').onclick=()=>v.currentTime=Math.max(0,v.currentTime-10);$('#forward10Btn').onclick=()=>v.currentTime=Math.min(v.duration||1e9,v.currentTime+10);seek.oninput=()=>{if(v.duration)v.currentTime=v.duration*Number(seek.value)/1000};$('#speedBtn').onclick=()=>playerMenu('speed');$('#qualityBtn').onclick=()=>playerMenu('quality');$('#subtitleBtn').onclick=()=>playerMenu('sub');$('#fullScreenBtn').onclick=()=>stage.requestFullscreen?.();$('#nativeFullBtn').onclick=()=>v.webkitEnterFullscreen?.();$('#closePlayer').onclick=()=>{v.pause();v.removeAttribute('src');v.load();close('playerOverlay')}} function fmt(s){if(!isFinite(s))return'00:00';s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
async function renderRouteV6(){applyTheme();document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';const r=parseRoute().split('/');window.scrollTo(0,0);try{if(r[0]==='home')await home();else if(r[0]==='discover')await discover(r[1]||'all');else if(r[0]==='genre')await genrePage(r[1]||'movie',r[2]||'all');else if(r[0]==='details')await detailPage(r[1],r[2],r[3]||1,r[4]||1);else if(r[0]==='manga')await ani('manga');else if(r[0]==='anime')await ani('anime');else if(r[0]==='books')await books();else if(r[0]==='music')await music();else if(r[0]==='mylist')mylist();else await home()}catch(e){console.error(e);$('#view').innerHTML=`<div class="page"><h1>RWL Movies</h1><div class="empty">${esc(e.message)}</div></div>`}bindDynamic()}

// ===== RWL Movies Web v7: app-parity layer =====
const V7='7.0';
function jget(k,d){try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch{return d}}
function jset(k,v){localStorage.setItem(k,JSON.stringify(v))}
function setting(k,d=true){const p=jget('rwlPrefs',{});return p[k]===undefined?d:!!p[k]}
function setSetting(k,v){const p=jget('rwlPrefs',{});p[k]=v;jset('rwlPrefs',p)}
function continueItems(){return jget('rwlContinue',[])}
function saveContinueItem(item){if(!item?.id)return;let a=continueItems().filter(x=>!(x.id==item.id&&x.type===item.type&&x.season==item.season&&x.episode==item.episode));if(item.duration&&item.position/item.duration>.96)return jset('rwlContinue',a);a.unshift(item);jset('rwlContinue',a.slice(0,30))}
function downloads(){return jget('rwlDownloads',[])}
function saveDownload(x){let a=downloads().filter(y=>y.url!==x.url);a.unshift(x);jset('rwlDownloads',a.slice(0,60))}
function cleanHtml(s){const d=document.createElement('div');d.innerHTML=String(s||'');return d.textContent||''}
function dock(){const items=[['home','⌂',tr('الرئيسية','Home')],['discover','◈',tr('استكشاف','Discover')],['live','▣',tr('بث مباشر','Live')],['manga','▤',tr('مانجا','Manga')],['books','▥',tr('كتب','Books')],['audiobooks','◉',tr('كتب صوتية','Audio')],['anime','✦',tr('أنمي','Anime')],['music','♫',tr('موسيقى','Music')],['downloads','⇩',tr('التنزيلات','Downloads')],['mylist','♥',tr('قائمتي','My List')]];$('#dock').innerHTML=items.map(([k,i,n])=>`<button class="dockBtn ${state.page===k?'active':''}" data-route="${k}"><span class="dockIcon">${i}</span><span>${n}</span></button>`).join('');bindDynamic()}
function featureRail(){return `<section class="section"><div class="sectionHead"><h2>${tr('أدوات RWL','RWL Tools')}</h2></div><div class="featureRail"><button data-route="calendar"><span>▦</span><b>${tr('تقويم الحلقات','TV Calendar')}</b></button><button data-route="quiz"><span>✦</span><b>${tr('اختبار التوصيات','Recommendation Quiz')}</b></button><button data-route="continue"><span>▶</span><b>${tr('أكمل المشاهدة','Continue Watching')}</b></button><button data-route="live"><span>▣</span><b>${tr('البث المباشر','Live TV')}</b></button><button data-route="audiobooks"><span>◉</span><b>${tr('كتب صوتية','Audiobooks')}</b></button><button data-route="downloads"><span>⇩</span><b>${tr('التنزيلات','Downloads')}</b></button></div></section>`}
function genreLabel(id){const ar={28:'أكشن',35:'كوميدي',10749:'رومانسي',27:'رعب',878:'خيال علمي',16:'أنيميشن',80:'جريمة',10751:'عائلي',18:'دراما',53:'إثارة'};const en={28:'Action',35:'Comedy',10749:'Romance',27:'Horror',878:'Science Fiction',16:'Animation',80:'Crime',10751:'Family',18:'Drama',53:'Thriller'};return (state.lang==='ar'?ar:en)[id]||String(id)}
async function fillGenres(){const [m,t]=await Promise.all([api(`/v1/tmdb/genres?type=movie&language=${state.lang==='ar'?'ar-SA':'en-US'}`),api(`/v1/tmdb/genres?type=tv&language=${state.lang==='ar'?'ar-SA':'en-US'}`)]);state.genres={movie:m.genres||[],tv:t.genres||[]};const ids=[28,35,10749,27,878,16,80,10751,18,53];$('#genreGrid').innerHTML=ids.map(id=>`<div class="genreCard" data-route="genre/movie/${id}">${esc((state.genres.movie.find(g=>g.id===id)?.name)||genreLabel(id))}</div>`).join('')}
async function addGenreSections(){const ids=[35,10749,27,28,16,878,80,18];for(const id of ids){const d=await api(`/v1/tmdb/discover?type=movie&genre=${id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>null);if(d?.results)$('#view').insertAdjacentHTML('beforeend',section((state.genres?.movie||[]).find(g=>g.id===id)?.name||genreLabel(id),d.results,false,`genre/movie/${id}`))}bindDynamic()}
function continueSection(){const a=continueItems();if(!a.length)return'';const items=a.map(x=>({...x.item,media_type:x.type,_progress:x.duration?Math.min(100,x.position/x.duration*100):0,_season:x.season,_episode:x.episode}));return `<section class="section"><div class="sectionHead"><h2>${tr('أكمل المشاهدة','Continue Watching')}</h2><button data-route="continue">${tr('عرض الكل','See all')}</button></div><div class="horizontal">${items.map((x,i)=>`<article class="posterCard" data-detail="${x.media_type}/${x.id}/${x._season||1}/${x._episode||1}">${poster(x)?`<img src="${poster(x)}">`:''}<div class="posterShade"></div><div class="posterCopy"><b>${esc(title(x))}</b><small>${x.media_type==='tv'?`${tr('م','S')}${x._season||1} ${tr('ح','E')}${x._episode||1}`:''}</small><div class="progress"><i style="width:${x._progress||0}%"></i></div></div></article>`).join('')}</div></section>`}
function syncItems(){return jget('rwlSyncItems',[])}
function syncSection(){const a=syncItems();if(!a.length)return'';return `<section class="section"><div class="sectionHead"><h2>${tr('مزامنتي','Synced Watchlist')}</h2></div><div class="horizontal">${a.slice(0,20).map(x=>`<article class="posterCard syncCard" data-detail="${x.type}/${x.id}"><div class="syncPosterFallback">${x.type==='tv'?'TV':'MOVIE'}</div><div class="posterShade"></div><div class="posterCopy"><b>${esc(x.title)}</b><small>${esc([x.year,x.source].filter(Boolean).join(' • '))}</small></div></article>`).join('')}</div></section>`}
async function pullSync(provider){const c=jget('rwlSync',{}),clientId=provider==='trakt'?c.traktClient:c.simklClient,token=provider==='trakt'?c.traktToken:c.simklToken;if(!clientId||!token){toast(tr('أدخل بيانات المزامنة أولاً','Enter sync credentials first'));return}toast(tr('جاري المزامنة…','Syncing…'));try{const d=await api('/v1/web/sync',{method:'POST',body:JSON.stringify({provider,clientId,token})});const old=syncItems().filter(x=>x.source!==provider);jset('rwlSyncItems',[...(d.items||[]),...old].slice(0,300));toast(`${provider}: ${(d.items||[]).length}`)}catch(e){toast(`${provider}: ${e.message}`)}}
async function home(){await homeV6();const v=$('#view');if(!setting('trailers',true))v.querySelector('.heroVideo')?.remove();const hero=v.querySelector('.hero');if(hero)hero.insertAdjacentHTML('afterend',(setting('continue',true)?continueSection():'')+syncSection()+featureRail());bindDynamic()}

async function detailPage(type,id,season=1,episode=1){await detailPageV6(type,id,season,episode);const d=state.detail;const trailer=(d.videos?.results||[]).find(v=>v.site==='YouTube'&&['Trailer','Teaser'].includes(v.type));const body=$('.detailBody');if(body){const info=`<section class="detailMetaGrid"><div><b>${tr('التقييم','Rating')}</b><span>${d.vote_average?Number(d.vote_average).toFixed(1):'—'}</span></div><div><b>${tr('المدة','Runtime')}</b><span>${d.runtime?d.runtime+' min':(d.episode_run_time?.[0]?d.episode_run_time[0]+' min':'—')}</span></div><div><b>${tr('التصنيفات','Genres')}</b><span>${(d.genres||[]).map(g=>g.name).join(' · ')||'—'}</span></div><div><b>IMDb</b><span>${d.external_ids?.imdb_id||'—'}</span></div></section>`;body.insertAdjacentHTML('afterbegin',info)}
 if(trailer&&$('#trailerBtn'))$('#trailerBtn').onclick=()=>openTrailer(trailer.key);
 bindDynamic()}
function openTrailer(key){let ov=$('#trailerOverlay');if(!ov){document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="trailerOverlay"><div class="trailerModal"><button class="circleClose" id="closeTrailer">×</button><iframe id="trailerFrame" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe></div></div>`);ov=$('#trailerOverlay');$('#closeTrailer').onclick=()=>{const f=$('#trailerFrame');f.src='';close('trailerOverlay')}}$('#trailerFrame').src=`https://www.youtube.com/embed/${key}?autoplay=1&playsinline=1&rel=0`;open('trailerOverlay')}

async function calendarPage(){state.page='calendar';dock();setTop(tr('تقويم الحلقات','TV Calendar'));const d=await api(`/v1/tmdb/calendar?language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({results:[]}));$('#view').innerHTML=`<div class="page"><div class="pageTitleRow"><div><h1>${tr('تقويم الحلقات','TV Shows Airing Calendar')}</h1><p>${tr('المسلسلات المعروضة والقادمة الآن','Shows airing now and today')}</p></div></div><div class="calendarGrid">${(d.results||[]).map(x=>`<article class="calendarCard" data-detail="tv/${x.id}">${x.backdrop_path?`<img src="${IMG}w500${x.backdrop_path}">`:''}<div><b>${esc(title(x))}</b><small>${esc(x.first_air_date||'')}</small><p>${esc((x.overview||'').slice(0,160))}</p></div></article>`).join('')||`<div class="empty">${tr('لا توجد بيانات الآن','No calendar data')}</div>`}</div></div>`;bindDynamic()}
async function quizPage(){state.page='quiz';dock();setTop(tr('اختبار التوصيات','Recommendation Quiz'));if(!state.genres)await fillGenres().catch(()=>{});const gs=(state.genres?.movie||[]).slice(0,18);$('#view').innerHTML=`<div class="page quizPage"><h1>${tr('وش ودك تشوف اليوم؟','What are you in the mood for?')}</h1><p>${tr('اختر نوع أو أكثر وخلك علينا.','Pick one or more genres and RWL will recommend titles.')}</p><div class="quizChoices">${gs.map(g=>`<button class="genreChoice" data-g="${g.id}">${esc(g.name)}</button>`).join('')}</div><div class="actions"><button class="primary" id="quizGo">✦ ${tr('اقترح لي','Recommend')}</button><button class="secondary" id="quizReset">${tr('إعادة','Reset')}</button></div><div id="quizResults" class="mediaGrid"></div></div>`;const selected=new Set();$$('.genreChoice').forEach(b=>b.onclick=()=>{selected.has(b.dataset.g)?selected.delete(b.dataset.g):selected.add(b.dataset.g);b.classList.toggle('active')});$('#quizReset').onclick=()=>{$$('.genreChoice').forEach(x=>x.classList.remove('active'));selected.clear();$('#quizResults').innerHTML=''};$('#quizGo').onclick=async()=>{const ids=[...selected];if(!ids.length)return toast(tr('اختر تصنيف واحد على الأقل','Pick at least one genre'));const out=[];for(const g of ids.slice(0,3)){const d=await api(`/v1/tmdb/discover?type=movie&genre=${g}&language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({results:[]}));out.push(...(d.results||[]).slice(0,8))}const seen=new Set();const uniq=out.filter(x=>!seen.has(x.id)&&seen.add(x.id)).sort((a,b)=>(b.vote_average||0)-(a.vote_average||0));$('#quizResults').innerHTML=row(uniq);bindDynamic()}}
function continuePage(){state.page='continue';dock();setTop(tr('أكمل المشاهدة','Continue Watching'));const a=continueItems();$('#view').innerHTML=`<div class="page"><h1>${tr('أكمل المشاهدة','Continue Watching')}</h1><div class="mediaGrid">${a.map(x=>`<article class="posterCard" data-detail="${x.type}/${x.id}/${x.season||1}/${x.episode||1}">${x.item&&poster(x.item)?`<img src="${poster(x.item)}">`:''}<div class="posterShade"></div><div class="posterCopy"><b>${esc(x.title||title(x.item))}</b><small>${fmt(x.position)} / ${fmt(x.duration)}</small><div class="progress"><i style="width:${x.duration?x.position/x.duration*100:0}%"></i></div></div></article>`).join('')||`<div class="empty">${tr('ما عندك شيء تكمله حالياً','Nothing to continue yet')}</div>`}</div></div>`;bindDynamic()}

function parseM3U(text){const lines=String(text||'').split(/\r?\n/),out=[];let meta=null;for(const raw of lines){const l=raw.trim();if(l.startsWith('#EXTINF')){const name=(l.split(',').slice(1).join(',')||'Channel').trim();const logo=(l.match(/tvg-logo="([^"]+)"/)||[])[1]||'';const group=(l.match(/group-title="([^"]+)"/)||[])[1]||'';meta={name,logo,group}}else if(l&& !l.startsWith('#')&&meta){out.push({...meta,url:l});meta=null}}return out}
function livePage(){state.page='live';dock();setTop(tr('بث مباشر','Live TV'));const channels=jget('rwlIptvChannels',[]);$('#view').innerHTML=`<div class="page"><div class="pageTitleRow"><div><h1>${tr('بث مباشر','Live TV')}</h1><p>${tr('استورد ملف M3U أو استخدم قائمتك المحفوظة.','Import an M3U playlist or use your saved channels.')}</p></div><label class="primary fileBtn">＋ ${tr('استيراد M3U','Import M3U')}<input id="m3uFile" type="file" accept=".m3u,.m3u8,text/plain" hidden></label></div><input id="channelSearch" class="searchInput" placeholder="${tr('بحث بالقنوات…','Search channels…')}"><div id="channelGrid" class="channelGrid"></div></div>`;const render=(q='')=>{$('#channelGrid').innerHTML=channels.filter(c=>c.name.toLowerCase().includes(q.toLowerCase())||c.group.toLowerCase().includes(q.toLowerCase())).slice(0,500).map((c,i)=>`<button class="channelCard" data-ch="${i}">${c.logo?`<img src="${esc(c.logo)}">`:'<span class="channelFallback">TV</span>'}<div><b>${esc(c.name)}</b><small>${esc(c.group)}</small></div></button>`).join('')||`<div class="empty">${tr('استورد قائمة M3U لعرض القنوات','Import an M3U playlist to see channels')}</div>`;$$('[data-ch]').forEach(b=>b.onclick=()=>playLoose(channels[Number(b.dataset.ch)],'RWL LIVE'))};render();$('#channelSearch').oninput=e=>render(e.target.value);$('#m3uFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const t=await f.text();const a=parseM3U(t);jset('rwlIptvChannels',a);toast(`${a.length} ${tr('قناة','channels')}`);livePage()}}
function playLoose(item,lane='RWL DIRECT'){state.activeServer={url:item.url,qualities:[],lane:'direct'};state.detail={id:'local-'+Date.now(),title:item.name||item.title||'RWL',name:item.name||item.title||'RWL'};$('#playerTitle').textContent=item.name||item.title||'RWL';$('#playerServer').textContent='';$('#playerLane').textContent=lane;const v=$('#webPlayer');v.src=item.url;open('playerOverlay');v.play().catch(()=>{})}

async function mangaPage(){state.page='manga';dock();setTop(tr('مانجا','Manga'));$('#view').innerHTML=`<div class="page"><div class="pageTitleRow"><div><h1>${tr('مانجا','Manga')}</h1><p>${tr('بحث، فصول وقارئ مانجا كامل','Search, chapters and reader')}</p></div></div><input id="mangaSearch" class="searchInput" placeholder="${tr('ابحث عن مانجا…','Search manga…')}"><div id="mangaGrid" class="mediaGrid"><div class="empty">${tr('جاري التحميل…','Loading…')}</div></div></div>`;const load=async q=>{const d=await api(`/v1/web/manga?mode=search&query=${encodeURIComponent(q||'')}`).catch(()=>({items:[]}));$('#mangaGrid').innerHTML=(d.items||[]).map(x=>`<article class="posterCard" data-route="manga-details/${x.id}">${x.cover?`<img src="${esc(x.cover)}">`:''}<div class="posterShade"></div><div class="posterCopy"><b>${esc(x.title)}</b><small>${esc((x.tags||[]).slice(0,2).join(' • '))}</small></div></article>`).join('')||`<div class="empty">${tr('تعذر تحميل المانجا','Manga unavailable')}</div>`;bindDynamic()};await load('');let tm;$('#mangaSearch').oninput=e=>{clearTimeout(tm);tm=setTimeout(()=>load(e.target.value),400)}}
async function mangaDetails(id){state.page='manga';dock();const [d,ch]=await Promise.all([api(`/v1/web/manga?mode=details&id=${encodeURIComponent(id)}`),api(`/v1/web/manga?mode=chapters&id=${encodeURIComponent(id)}`)]);const m=d.item||{};$('#view').innerHTML=`<div class="page mangaDetail"><div class="bookHero">${m.cover?`<img src="${esc(m.cover)}">`:''}<div><h1>${esc(m.title||'Manga')}</h1><p>${esc(m.description||'')}</p><div class="chips">${(m.tags||[]).slice(0,8).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div></div><h2>${tr('الفصول','Chapters')}</h2><div class="chapterList">${(ch.chapters||[]).map(x=>`<button data-route="manga-reader/${x.id}"><b>${tr('الفصل','Chapter')} ${esc(x.chapter||'?')} ${esc(x.title||'')}</b><small>${esc(x.language||'')}</small></button>`).join('')||`<div class="empty">${tr('لا توجد فصول مترجمة متاحة','No translated chapters available')}</div>`}</div></div>`;bindDynamic()}
async function mangaReader(chapter){state.page='manga';dock();const d=await api(`/v1/web/manga?mode=pages&id=${encodeURIComponent(chapter)}`);$('#view').innerHTML=`<div class="mangaReader"><div class="readerTop"><button class="secondary" onclick="history.back()">←</button><b>${tr('قارئ المانجا','Manga Reader')}</b><span>${(d.pages||[]).length}</span></div>${(d.pages||[]).map((u,i)=>`<img src="${esc(u)}" loading="lazy" alt="${i+1}">`).join('')}</div>`}
async function ani(kind){if(kind==='manga')return mangaPage();return aniV6(kind)}

async function books(){state.page='books';dock();setTop(tr('كتب','Books'));$('#view').innerHTML=`<div class="page"><div class="pageTitleRow"><div><h1>${tr('مكتبة الكتب','Books Library')}</h1><p>${tr('ابحث واقرأ معلومات الكتب واحفظ تقدمك.','Search books and keep your reading list.')}</p></div></div><input id="bookSearch" class="searchInput" placeholder="${tr('ابحث عن كتاب…','Search books…')}"><div id="bookGrid" class="mediaGrid"></div></div>`;const load=async q=>{const d=await api(`/v1/web/books?query=${encodeURIComponent(q||'subject:fiction')}`).catch(()=>({books:[]}));$('#bookGrid').innerHTML=(d.books||[]).map(b=>`<article class="posterCard" data-book="${esc(b.id)}">${b.image?`<img src="${esc(b.image)}">`:''}<div class="posterShade"></div><div class="posterCopy"><b>${esc(b.title)}</b><small>${esc((b.authors||[]).join(', '))}</small></div></article>`).join('')||`<div class="empty">${tr('تعذر تحميل الكتب','Books unavailable')}</div>`;$$('[data-book]').forEach(el=>el.onclick=()=>bookDetail((d.books||[]).find(b=>b.id===el.dataset.book)))};await load('');let tm;$('#bookSearch').oninput=e=>{clearTimeout(tm);tm=setTimeout(()=>load(e.target.value),350)}}
function bookDetail(b){if(!b)return;$('#view').innerHTML=`<div class="page"><div class="bookHero">${b.image?`<img src="${esc(b.image)}">`:''}<div><h1>${esc(b.title)}</h1><h3>${esc((b.authors||[]).join(', '))}</h3><p>${esc(b.description||'')}</p><div class="actions">${b.infoLink?`<a class="primary linkBtn" href="${esc(b.infoLink)}" target="_blank">${tr('فتح الكتاب / المعاينة','Open / Preview')}</a>`:''}<button class="secondary" id="saveBook">♡ ${tr('حفظ','Save')}</button></div></div></div></div>`;$('#saveBook').onclick=()=>{let a=jget('rwlBooks',[]).filter(x=>x.id!==b.id);a.unshift(b);jset('rwlBooks',a);toast(tr('تم الحفظ','Saved'))}}

async function audiobooksPage(){state.page='audiobooks';dock();setTop(tr('كتب صوتية','Audiobooks'));$('#view').innerHTML=`<div class="page"><div class="pageTitleRow"><div><h1>${tr('كتب صوتية','Audiobooks')}</h1><p>${tr('مكتبة عامة + ملفاتك المحلية','Public library + your local audio files')}</p></div><label class="primary fileBtn">＋ ${tr('ملفات صوتية','Audio Files')}<input id="localAudio" type="file" accept="audio/*" multiple hidden></label></div><input id="audioSearch" class="searchInput" placeholder="${tr('ابحث عن كتاب صوتي…','Search audiobooks…')}"><div id="audioList" class="libraryList"></div></div>`;const load=async q=>{const d=await api(`/v1/web/audiobooks?query=${encodeURIComponent(q||'')}`).catch(()=>({books:[]}));$('#audioList').innerHTML=(d.books||[]).map(x=>`<button class="libraryItem audiobookItem" data-audio-book="${x.id}"><span class="audioCover">◉</span><div><b>${esc(x.title)}</b><small>${esc(x.author||'LibriVox')}</small></div><span>›</span></button>`).join('')||`<div class="empty">${tr('تعذر تحميل الكتب الصوتية','Audiobooks unavailable')}</div>`;$$('[data-audio-book]').forEach(b=>b.onclick=()=>audiobookDetail(b.dataset.audioBook))};await load('');let tm;$('#audioSearch').oninput=e=>{clearTimeout(tm);tm=setTimeout(()=>load(e.target.value),350)};$('#localAudio').onchange=e=>{const fs=[...(e.target.files||[])];if(!fs.length)return;const urls=fs.map(f=>({name:f.name,url:URL.createObjectURL(f)}));$('#audioList').insertAdjacentHTML('afterbegin',urls.map((x,i)=>`<button class="libraryItem" data-local-audio="${i}"><span class="audioCover">♪</span><div><b>${esc(x.name)}</b><small>${tr('ملف محلي','Local file')}</small></div><span>▶</span></button>`).join(''));$$('[data-local-audio]').forEach(b=>b.onclick=()=>playLoose({name:urls[Number(b.dataset.localAudio)].name,url:urls[Number(b.dataset.localAudio)].url},'RWL AUDIO'))}}
async function audiobookDetail(id){const d=await api(`/v1/web/audiobooks?id=${encodeURIComponent(id)}`);const b=d.book||{};$('#view').innerHTML=`<div class="page"><h1>${esc(b.title||tr('كتاب صوتي','Audiobook'))}</h1><p>${esc(b.description||'')}</p><div class="libraryList">${(b.sections||[]).map((s,i)=>`<button class="libraryItem" data-section="${i}"><span class="audioCover">${i+1}</span><div><b>${esc(s.title||`${tr('الفصل','Chapter')} ${i+1}`)}</b><small>${esc(s.duration||'')}</small></div><span>▶</span></button>`).join('')}</div></div>`;$$('[data-section]').forEach(x=>x.onclick=()=>{const s=b.sections[Number(x.dataset.section)];playLoose({name:s.title||b.title,url:s.url},'RWL AUDIO')})}

async function music(){state.page='music';dock();setTop(tr('موسيقى','Music'));$('#view').innerHTML=`<div class="page"><h1>${tr('موسيقى','Music')}</h1><input id="musicSearch" class="searchInput" placeholder="${tr('بحث موسيقى…','Search music…')}"><div id="musicList" class="libraryList"></div></div>`;const load=async q=>{const d=await api(`/v1/web/music?query=${encodeURIComponent(q||'')}`).catch(()=>({tracks:[]}));$('#musicList').innerHTML=(d.tracks||[]).map((t,i)=>`<div class="libraryItem">${t.cover?`<img src="${esc(t.cover)}">`:''}<div><b>${esc(t.title)}</b><small>${esc(t.artist)} · ${esc(t.album)}</small></div><button class="secondary" data-track="${i}">▶</button></div>`).join('');$$('[data-track]').forEach(b=>b.onclick=()=>{const t=d.tracks[Number(b.dataset.track)];playLoose({name:`${t.artist} — ${t.title}`,url:t.preview},'RWL MUSIC')})};await load('');let tm;$('#musicSearch').oninput=e=>{clearTimeout(tm);tm=setTimeout(()=>load(e.target.value),300)}}

function downloadsPage(){state.page='downloads';dock();setTop(tr('التنزيلات','Downloads'));const a=downloads();$('#view').innerHTML=`<div class="page"><h1>${tr('التنزيلات','Downloads')}</h1><p>${tr('في Safari قد يفتح الملف في تبويب جديد بدل الحفظ مباشرة.','Safari may open the media in a new tab instead of saving it directly.')}</p><div class="libraryList">${a.map((x,i)=>`<div class="libraryItem"><span class="audioCover">⇩</span><div><b>${esc(x.title)}</b><small>${esc(x.server||'')}</small></div><a class="secondary linkBtn" href="${esc(x.url)}" target="_blank" download>${tr('تنزيل','Download')}</a></div>`).join('')||`<div class="empty">${tr('لا توجد تنزيلات','No downloads')}</div>`}</div></div>`}

function settings(){const cfg=jget('rwlDebrid',{provider:'torbox',key:''}),prefs=jget('rwlPrefs',{}),sync=jget('rwlSync',{});$('#settingsContent').innerHTML=`
<section class="settingsGroup"><h3>${tr('المظهر والواجهة','Appearance & Interface')}</h3>
<div class="settingRow"><div><b>${tr('لغة التطبيق','App Language')}</b></div><select id="langSel"><option value="ar">العربية</option><option value="en">English</option></select></div>
<div class="settingRow"><div><b>${tr('الثيم','Theme')}</b></div><select id="themeSel">${Object.keys(themes).map(k=>`<option value="${k}">${k}</option>`).join('')}</select></div>
<div class="settingRow"><div><b>Liquid Glass</b></div><label class="switch"><input id="glassToggle" type="checkbox" ${setting('glass',true)?'checked':''}><span></span></label></div></section>
<section class="settingsGroup"><h3>${tr('الرئيسية والتوصيات','Home & Recommendations')}</h3>
${toggleRow('calendarToggle',tr('TV Airing Calendar','TV Airing Calendar'),setting('calendar',true))}${toggleRow('quizToggle',tr('AI Recommendation Quiz','AI Recommendation Quiz'),setting('quiz',true))}${toggleRow('continueToggle',tr('أكمل المشاهدة','Continue Watching'),setting('continue',true))}${toggleRow('trailersToggle',tr('تشغيل التريلر بالخلفية','Background trailers'),setting('trailers',true))}</section>
<section class="settingsGroup"><h3>${tr('الفيديو والترجمة','Video & Subtitles')}</h3>
<div class="settingRow"><div><b>${tr('سرعة التشغيل الافتراضية','Default playback speed')}</b></div><select id="defaultSpeed">${[.5,.75,1,1.25,1.5,2].map(x=>`<option value="${x}">${x}×</option>`).join('')}</select></div>
${toggleRow('skipToggle',tr('أزرار تخطي المقدمة والنهاية','Skip intro/credits buttons'),setting('skip',true))}<div class="settingRow"><div><b>${tr('إزاحة الترجمة','Subtitle offset')}</b><small>${tr('يمكن تعديلها من المشغل أيضاً','Also adjustable in player')}</small></div><span id="subOffsetLabel">${Number(localStorage.getItem('rwlSubOffset')||0).toFixed(2)}s</span></div></section>
<section class="settingsGroup"><h3>${tr('Debrid والبث السحابي','Debrid & Cloud Streaming')}</h3><div class="settingRow"><div><b>${tr('الخدمة','Service')}</b></div><select id="debridProvider"><option value="torbox">TorBox</option><option value="realdebrid">Real-Debrid</option><option value="alldebrid">AllDebrid</option><option value="premiumize">Premiumize</option><option value="debridlink">Debrid-Link</option></select></div><div class="settingRow"><div><b>API Key</b><small>${tr('يحفظ على جهازك فقط','Stored only on this device')}</small></div><input id="debridKey" type="password" value="${esc(cfg.key||'')}" autocomplete="off"></div><div class="settingRow"><button id="saveDebrid" class="primary">${tr('حفظ','Save')}</button></div></section>
<section class="settingsGroup"><h3>${tr('Trakt / Simkl','Trakt / Simkl')}</h3><div class="settingRow"><div><b>Trakt Client ID</b></div><input id="traktClient" value="${esc(sync.traktClient||'')}"></div><div class="settingRow"><div><b>Trakt Access Token</b></div><input id="traktToken" type="password" value="${esc(sync.traktToken||'')}"></div><div class="settingRow"><div><b>Simkl Client ID</b></div><input id="simklClient" value="${esc(sync.simklClient||'')}"></div><div class="settingRow"><div><b>Simkl Access Token</b></div><input id="simklToken" type="password" value="${esc(sync.simklToken||'')}"></div><div class="settingRow"><button id="saveSync" class="primary">${tr('حفظ المزامنة','Save Sync')}</button><button id="pullTrakt" class="secondary">Trakt Sync</button><button id="pullSimkl" class="secondary">Simkl Sync</button></div></section>
<section class="settingsGroup"><h3>${tr('Built-in Providers','Built-in Providers')}</h3><div class="settingRow"><div><b>RWL DIRECT</b><small>${tr('يجلب جميع المصادر المتاحة ويعرضها كسيرفرات فقط.','Loads all available providers and shows only Server labels.')}</small></div><span>45+</span></div><div class="settingRow"><div><b>RWL TOT</b><small>${tr('مصادر torrent عبر خدمة Debrid المختارة.','Torrent sources through the selected Debrid service.')}</small></div><span>ON</span></div></section>
<section class="settingsGroup"><h3>${tr('النسخ والبيانات','Backup & Restore')}</h3><div class="settingRow"><button id="exportCfg" class="secondary">${tr('تصدير JSON','Export JSON')}</button><label class="secondary fileBtn">${tr('استيراد JSON','Import JSON')}<input id="importCfg" type="file" accept="application/json" hidden></label></div><div class="settingRow"><button id="clearData" class="secondary">${tr('مسح بيانات الموقع','Clear local data')}</button></div></section>`;
$('#langSel').value=state.lang;$('#themeSel').value=localStorage.getItem('rwlTheme')||'cyan';$('#debridProvider').value=cfg.provider||'torbox';$('#defaultSpeed').value=localStorage.getItem('rwlDefaultSpeed')||'1';
$('#langSel').onchange=e=>{localStorage.setItem('rwlLang',e.target.value);state.lang=e.target.value;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr'};$('#themeSel').onchange=e=>applyTheme(e.target.value);$('#glassToggle').onchange=e=>{setSetting('glass',e.target.checked);document.body.classList.toggle('noGlass',!e.target.checked)};[['calendarToggle','calendar'],['quizToggle','quiz'],['continueToggle','continue'],['trailersToggle','trailers'],['skipToggle','skip']].forEach(([id,k])=>$('#'+id).onchange=e=>setSetting(k,e.target.checked));$('#defaultSpeed').onchange=e=>localStorage.setItem('rwlDefaultSpeed',e.target.value);$('#saveDebrid').onclick=()=>{jset('rwlDebrid',{provider:$('#debridProvider').value,key:$('#debridKey').value.trim()});toast(tr('تم الحفظ','Saved'))};$('#saveSync').onclick=()=>{jset('rwlSync',{traktClient:$('#traktClient').value.trim(),traktToken:$('#traktToken').value.trim(),simklClient:$('#simklClient').value.trim(),simklToken:$('#simklToken').value.trim()});toast(tr('تم الحفظ','Saved'))};$('#pullTrakt').onclick=async()=>{document.querySelector('#saveSync').click();await pullSync('trakt')};$('#pullSimkl').onclick=async()=>{document.querySelector('#saveSync').click();await pullSync('simkl')};$('#exportCfg').onclick=()=>{const keys=['rwlLang','rwlTheme','rwlPrefs','rwlDebrid','rwlSync','rwlFavs','rwlContinue','rwlIptvChannels','rwlBooks'];const obj={version:V7};for(const k of keys)obj[k]=localStorage.getItem(k);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download='RWL-Movies-backup.json';a.click()};$('#importCfg').onchange=async e=>{try{const o=JSON.parse(await e.target.files[0].text());for(const [k,v] of Object.entries(o))if(k!=='version'&&typeof v==='string')localStorage.setItem(k,v);toast(tr('تم الاستيراد','Imported'));setTimeout(()=>location.reload(),600)}catch{toast(tr('ملف غير صالح','Invalid file'))}};$('#clearData').onclick=()=>{if(confirm(tr('مسح جميع بيانات الموقع؟','Clear all local data?'))){localStorage.clear();location.reload()}};open('settingsOverlay')}
function toggleRow(id,label,on){return `<div class="settingRow"><div><b>${label}</b></div><label class="switch"><input id="${id}" type="checkbox" ${on?'checked':''}><span></span></label></div>`}

function subtitleShift(delta){const n=Math.round((Number(localStorage.getItem('rwlSubOffset')||0)+delta)*4)/4;localStorage.setItem('rwlSubOffset',String(n));$('#subShiftLabel').textContent=(n>0?'+':'')+n.toFixed(2)+'s';const active=state._activeSubtitle;if(active!==undefined&&active!==null)setSubtitle(active);toast(`${tr('إزاحة الترجمة','Subtitle offset')}: ${(n>0?'+':'')+n.toFixed(2)}s`)}
function shiftTimecode(tc,delta){const m=tc.match(/(?:(\d+):)?(\d{2}):(\d{2})[.,](\d{3})/);if(!m)return tc;let ms=((Number(m[1]||0)*3600+Number(m[2])*60+Number(m[3]))*1000+Number(m[4]))+delta*1000;ms=Math.max(0,Math.round(ms));const h=Math.floor(ms/3600000),mi=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000),x=ms%1000;return `${String(h).padStart(2,'0')}:${String(mi).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(x).padStart(3,'0')}`}
function shiftVtt(text,delta){return text.replace(/((?:\d+:)?\d{2}:\d{2}[.,]\d{3})\s+-->\s+((?:\d+:)?\d{2}:\d{2}[.,]\d{3})/g,(_,a,b)=>`${shiftTimecode(a,delta)} --> ${shiftTimecode(b,delta)}`)}
async function setSubtitle(v){const video=$('#webPlayer');[...video.querySelectorAll('track')].forEach(x=>x.remove());state._activeSubtitle=v;if(v==='off'){state._activeSubtitle=null;return}const s=state.subtitles[Number(v)];if(!s)return;try{const txt=await fetch(s.url).then(r=>r.text());let vtt=txt.startsWith('WEBVTT')?txt:'WEBVTT\n\n'+txt.replace(/,(\d{3})/g,'.$1');vtt=shiftVtt(vtt,Number(localStorage.getItem('rwlSubOffset')||0));const blob=URL.createObjectURL(new Blob([vtt],{type:'text/vtt'}));const t=document.createElement('track');t.kind='subtitles';t.label=s.lang||'Subtitle';t.srclang=(s.lang||'en').slice(0,2);t.src=blob;t.default=true;video.appendChild(t);setTimeout(()=>{if(t.track)t.track.mode='showing'},300)}catch{toast(tr('تعذر تحميل الترجمة','Subtitle failed'))}}
function playerMenu(type){const m=$('#floatingMenu');m.innerHTML='';if(type==='audio'){const tracks=$('#webPlayer').audioTracks;if(tracks&&tracks.length){for(let i=0;i<tracks.length;i++)m.insertAdjacentHTML('beforeend',`<button data-audio="${i}">${esc(tracks[i].label||tracks[i].language||`Audio ${i+1}`)}</button>`);$$('[data-audio]').forEach(b=>b.onclick=()=>{for(let i=0;i<tracks.length;i++)tracks[i].enabled=i===Number(b.dataset.audio);m.classList.remove('open')})}else m.innerHTML=`<button>${tr('لا توجد مسارات صوت قابلة للاختيار','No selectable audio tracks')}</button>`}else if(type==='speed'){[.5,.75,1,1.25,1.5,1.75,2].forEach(x=>m.insertAdjacentHTML('beforeend',`<button data-speed="${x}">${x}×</button>`));$$('[data-speed]').forEach(b=>b.onclick=()=>{$('#webPlayer').playbackRate=Number(b.dataset.speed);$('#speedBtn').textContent=b.dataset.speed+'×';m.classList.remove('open')})}else if(type==='quality'){const q=state.activeServer?.qualities||[];m.innerHTML=`<button data-q="">AUTO</button>`+q.map(x=>`<button data-q="${esc(x.url)}">${esc(x.label||'Quality')}</button>`).join('');$$('[data-q]').forEach(b=>b.onclick=()=>{const v=$('#webPlayer'),pos=v.currentTime,was=!v.paused;if(b.dataset.q)v.src=b.dataset.q;else v.src=state.activeServer.url;v.currentTime=pos;if(was)v.play();m.classList.remove('open')})}else if(type==='sub'){m.innerHTML=`<button data-sub="off">${tr('إيقاف الترجمة','Subtitles Off')}</button>`+(state.subtitles||[]).slice(0,120).map((s,i)=>`<button data-sub="${i}">${esc((s.lang||'')+' '+(s.name||s.label||''))}</button>`).join('');$$('[data-sub]').forEach(b=>b.onclick=async()=>{await setSubtitle(b.dataset.sub);m.classList.remove('open')})}m.classList.toggle('open')}
function bindPlayer(){const v=$('#webPlayer'),stage=$('#videoStage'),seek=$('#seekBar');const sync=()=>{$('#playPauseBtn').textContent=v.paused?'▶':'❚❚';stage.classList.toggle('paused',v.paused);$('#timeText').textContent=`${fmt(v.currentTime)} / ${fmt(v.duration)}`;seek.value=v.duration?Math.round(v.currentTime/v.duration*1000):0;if(setting('skip',true)){$('#skipIntroBtn').classList.toggle('show',v.currentTime>10&&v.currentTime<150);$('#skipCreditsBtn').classList.toggle('show',isFinite(v.duration)&&v.duration-v.currentTime<240&&v.duration-v.currentTime>15)}if(state.detail?.id&&isFinite(v.duration)&&v.duration>120&&Math.floor(v.currentTime)%5===0)saveContinueItem({type:state.type||'movie',id:state.detail.id,title:title(state.detail),item:state.detail,season:state.season,episode:state.episode,position:v.currentTime,duration:v.duration,updated:Date.now()})};v.onplay=sync;v.onpause=sync;v.ontimeupdate=sync;v.onloadedmetadata=()=>{v.playbackRate=Number(localStorage.getItem('rwlDefaultSpeed')||1);sync();const cw=continueItems().find(x=>x.id==state.detail?.id&&x.type===(state.type||'movie')&&x.season==state.season&&x.episode==state.episode);if(cw&&cw.position>10&&cw.position<(v.duration||Infinity)-20)v.currentTime=cw.position};$('#playPauseBtn').onclick=$('#centerPlay').onclick=()=>v.paused?v.play():v.pause();$('#back10Btn').onclick=()=>v.currentTime=Math.max(0,v.currentTime-10);$('#forward10Btn').onclick=()=>v.currentTime=Math.min(v.duration||1e9,v.currentTime+10);seek.oninput=()=>{if(v.duration)v.currentTime=v.duration*Number(seek.value)/1000};$('#speedBtn').onclick=()=>playerMenu('speed');$('#qualityBtn').onclick=()=>playerMenu('quality');$('#subtitleBtn').onclick=()=>playerMenu('sub');$('#audioBtn').onclick=()=>playerMenu('audio');$('#subBackBtn').onclick=()=>subtitleShift(-.25);$('#subForwardBtn').onclick=()=>subtitleShift(.25);$('#fullScreenBtn').onclick=()=>stage.requestFullscreen?.();$('#nativeFullBtn').onclick=()=>v.webkitEnterFullscreen?.();$('#skipIntroBtn').onclick=()=>v.currentTime=Math.min(v.duration||1e9,v.currentTime+85);$('#skipCreditsBtn').onclick=()=>v.currentTime=Math.max(0,(v.duration||0)-5);$('#downloadBtn').onclick=()=>{if(!state.activeServer?.url)return;const x={title:$('#playerTitle').textContent,server:$('#playerServer').textContent,url:state.activeServer.url,date:Date.now()};saveDownload(x);const a=document.createElement('a');a.href=x.url;a.target='_blank';a.download='';a.click();toast(tr('تمت إضافة رابط التنزيل','Download link saved'))};$('#closePlayer').onclick=()=>{sync();v.pause();v.removeAttribute('src');v.load();close('playerOverlay')};$('#subShiftLabel').textContent=(Number(localStorage.getItem('rwlSubOffset')||0)>0?'+':'')+Number(localStorage.getItem('rwlSubOffset')||0).toFixed(2)+'s'}

async function loadSources(type,id){$('#sourceStatus').textContent=tr('جاري البحث عن جميع السيرفرات…','Finding all servers…');let data=await api(`/v1/web/sources?${idsQuery(type,id)}`).catch(()=>({servers:[]}));let servers=data.servers||[];const cfg=jget('rwlDebrid',{});if(cfg?.key&&cfg?.provider){try{const t=await api(`/v1/web/torrents?${idsQuery(type,id)}`);for(const tor of (t.torrents||[]).slice(0,30)){const r=await api('/v1/web/debrid/resolve',{method:'POST',body:JSON.stringify({provider:cfg.provider,key:cfg.key,magnet:tor.magnet,filename:tor.filename,fileIndex:tor.fileIndex,season:state.season,episode:state.episode,cachedOnly:true})}).catch(()=>null);if(r?.ok&&r.url)servers.push({id:`user-${servers.length+1}`,label:`Server ${servers.length+1}`,lane:'p2p',url:r.url,qualities:[]});if(servers.length>=64)break}}catch{}}
 const unique=[];const seen=new Set();for(const s of servers){const k=s.url;if(!k||seen.has(k))continue;seen.add(k);unique.push(s)}servers=unique.slice(0,64);state.servers=servers;const direct=servers.filter(s=>s.lane!=='p2p'),tot=servers.filter(s=>s.lane==='p2p');$('#directLane').innerHTML=direct.length?`<h3>RWL DIRECT</h3><div class="sources">${direct.map((s,i)=>sourceButton(s,i)).join('')}</div>`:'';$('#totLane').innerHTML=tot.length?`<h3>RWL TOT</h3><div class="sources">${tot.map((s,i)=>sourceButton(s,direct.length+i)).join('')}</div>`:'';$('#sourceStatus').textContent=servers.length?`${servers.length} ${tr('سيرفر متاح','servers available')}`:tr('لا توجد مصادر حالياً','No sources available');$$('.source').forEach(b=>b.onclick=()=>playServer(servers[Number(b.dataset.i)],Number(b.dataset.i)+1,type,id))}

async function renderRoute(){applyTheme();document.body.classList.toggle('noGlass',!setting('glass',true));document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';const r=parseRoute().split('/');window.scrollTo(0,0);try{if(r[0]==='home')await home();else if(r[0]==='discover')await discover(r[1]||'all');else if(r[0]==='genre')await genrePage(r[1]||'movie',r[2]||'all');else if(r[0]==='details')await detailPage(r[1],r[2],r[3]||1,r[4]||1);else if(r[0]==='manga')await mangaPage();else if(r[0]==='manga-details')await mangaDetails(r[1]);else if(r[0]==='manga-reader')await mangaReader(r[1]);else if(r[0]==='anime')await aniV6('anime');else if(r[0]==='books')await books();else if(r[0]==='audiobooks')await audiobooksPage();else if(r[0]==='music')await music();else if(r[0]==='live')livePage();else if(r[0]==='calendar')await calendarPage();else if(r[0]==='quiz')await quizPage();else if(r[0]==='continue')continuePage();else if(r[0]==='downloads')downloadsPage();else if(r[0]==='mylist')mylist();else await home()}catch(e){console.error(e);$('#view').innerHTML=`<div class="page"><h1>RWL Movies</h1><div class="empty">${esc(e.message)}</div><div class="actions"><button class="primary" onclick="location.reload()">${tr('إعادة المحاولة','Retry')}</button></div></div>`}bindDynamic()}

function init(){bindPlayer();$('#settingsBtn').onclick=settings;$('#searchBtn').onclick=()=>open('searchOverlay');let st;$('#searchInput').oninput=e=>{clearTimeout(st);st=setTimeout(()=>search(e.target.value),260)};$$('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));window.addEventListener('hashchange',renderRoute);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});renderRoute()} init();
